head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/filing_common.js");
//문자열 길이 체크
//★Wcraft guide★ include부분 주석처리 -> include("../js/pf_listinvstg.js");
scwin.vScrenID = "ULDSTF09303.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vSecugrpID;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.pJsMarket = js_market;
scwin.gDepCd;
scwin.gBasIdx;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_SearchIsu.src = "../img/btn_search.gif";
        img_SearchIsu.setDisabled(false);
    } else if (initTyp == "X") {
        img_SearchIsu.src = "../img/btn_search_d.gif";
        img_SearchIsu.setDisabled(true);
    }
};
scwin.fn_initLabel = function(secugrpId) {
    edt_FLOW_NETASST_TOTAMT.setReadOnly(true);
    edt_FLOW_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
    edt_FORNCURR_NETASST_TOTAMT.setReadOnly(true);
    edt_FORNCURR_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
    edt_FORNFLOW_NETASST_TOTAMT.setReadOnly(true);
    edt_FORNFLOW_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
    edt_FORNCURR_LST_NAV.setReadOnly(true);
    edt_FORNCURR_LST_NAV.readonlybackcolor = '#b9d4f7';
    edt_FLOW_SHRS.setReadOnly(true);
    edt_FLOW_SHRS.readonlybackcolor = '#b9d4f7';
};
scwin.fn_searchCode = function() {
    /*
    00685-명의개서대행기관
    04774-PF구분코드	
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "TAX_TP_CD",
        cnm: "cmb_TAX_TP_CD"
    }, {
        cid: "ETF_REPLICA_METHD_TP_CD",
        cnm: "cmb_ETF_REPLICA_METHD_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='TRANSSTK_AGNT_CD', 'TAX_TP_CD', 'ETF_REPLICA_METHD_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (dts_Cod.getCellData(j, "CD_ENG_NM") == "TAX_TP_CD" || dts_Cod.getCellData(j, "CD_ENG_NM") == "ETF_REPLICA_METHD_TP_CD") {
                    if (strCbd == "") {
                        strCbd = "^ ";
                    }
                }
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_disableDistrMmDd = function() {
    var ori_btnSave = btn_Save.src;
    var ori_btn_Update = btn_Update.src;
    var chk_btnSave = "btn_save.gif";
    var chk_btn_Update = "btn_modify.gif";
    if ((ori_btnSave.indexOf(chk_btnSave) == -1) && (ori_btn_Update.indexOf(chk_btn_Update) == -1)) {
        img_Add.src = "../img/btn_arrowR_d.gif";
        img_del.src = "../img/btn_arrowL_d.gif";
        img_Add.setDisabled(true);
        img_del.setDisabled(true);
    } else {
        img_Add.src = "../img/btn_arrowR.gif";
        img_del.src = "../img/btn_arrowL.gif";
        img_Add.setDisabled(false);
        img_del.setDisabled(false);
    }
};
scwin.fn_getDistrBasMmDd = function() {
    if (dts_IsuItem.getTotalRow() > 0) {
        for (var i = 1; i <= 12; i++) {
            if (dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i) != "") {
                dts_DISTR_BAS_MMDD.insertRow();
                dts_DISTR_BAS_MMDD.setCellData(i, "EARNG_DISTR_BAS_MMDD", dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i));
            }
        }
        scwin.fn_DistrBasMmDdSetting(dts_DISTR_BAS_MMDD.getRowPosition());
    }
};
scwin.fn_DistrBasMmDdSetting = function(rPos) {
    if (dts_DISTR_BAS_MMDD.getTotalRow() > 0) {
        $c.stf.setObjectValue(txb_DISTR_BAS_MMDD, dts_DISTR_BAS_MMDD.getCellData(rPos, "EARNG_DISTR_BAS_MMDD"));
    }
};
scwin.fn_addDistrBasMmDd = function() {
    if (dts_DISTR_BAS_MMDD.getTotalRow() > 11) {
        $c.win.alert("[분배기준일]은  최대12개 입니다.");
        return false;
    } else {
        if (scwin.fn_dateCheck()) {
            grd_DISTR_BAS_MMDD.Redraw = false;
            dts_DISTR_BAS_MMDD.insertRow();
            dts_DISTR_BAS_MMDD.setCellData(dts_DISTR_BAS_MMDD.getRowPosition(), "EARNG_DISTR_BAS_MMDD", $c.stf.getObjectValue(txb_DISTR_BAS_MMDD));
            grd_DISTR_BAS_MMDD.Redraw = true;
        }
    }
};
scwin.fn_delDistrBasMmDd = function() {
    if (dts_DISTR_BAS_MMDD.getTotalRow() < 1) {
        $c.win.alert("삭제할 [분배기준일]이 없습니다.");
        return false;
    } else {
        $c.cp.removeRow(dts_DISTR_BAS_MMDD, dts_DISTR_BAS_MMDD.getRowPosition());
        scwin.fn_DistrBasMmDdSetting(dts_DISTR_BAS_MMDD.getRowPosition());
    }
};
scwin.fn_SaveDistrBasMmDd = function() {
    for (var i = 1, j = 12; i <= j; i++) {
        dts_IsuItem.setCellData(1, "EARNG_DISTR_BAS_MMDD" + i, dts_DISTR_BAS_MMDD.getCellData(i, "EARNG_DISTR_BAS_MMDD"));
    }
};
scwin.fn_dateCheck = function() {
    if ($c.stf.getObjectValue(txb_DISTR_BAS_MMDD) != "") {
        if ($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).length == 4) {
            if (parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(0, 2), 10) < 13 && parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(0, 2), 10) > 0) {
                if (parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(2, 4), 10) < 32 && parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(2, 4), 10) > 0) {

                } else {
                    $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                    txb_DISTR_BAS_MMDD.focus();
                    return false;
                }
            } else {
                $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                txb_DISTR_BAS_MMDD.focus();
                return false;
            }
        } else {
            $c.win.alert("올바른 [분배기준일]을 입력하세요.");
            txb_DISTR_BAS_MMDD.focus();
            return false;
        }
        return true;
    } else {
        $c.win.alert("올바른 [분배기준일]을 입력하세요.");
        txb_DISTR_BAS_MMDD.focus();
        return false;
    }
};
scwin.fn_searchLPCode = function() {
    var strCbdLP = "' ':"; //초기값
    dts_LP.DataID = "/listingCommon.do?method=listLeadCom";
    dts_LP.Reset();
    for (k = 1; k <= dts_LP.getTotalRow(); k++) {
        strCbdLP = strCbdLP + (strCbdLP == "" ? "" : ",") + dts_LP.getCellData(k, "VALUE") + ":" + dts_LP.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_LP, 'LP_MBR_NO', 'Data', strCbdLP);
};
scwin.fn_SetParZipCd = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    txb_ZIPCD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_ADDR.setValue((arrPar.length >= 2 ? arrPar[1] : "")); /*ORG SRC: dts_IsuItem.NameValue(1, "ZIPCD_SEQ") = (arrPar.length >= 3 ? arrPar[2] : "");*/ X = (arrPar.length >= 3 ? arrPar[2] : "");
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SEC;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm.setValue(arrPar[0].ISU_NM);
        scwin.fn_getPfIsu_read_sync(arrPar[0].ISU_CD);
        var parentWin = $c.frame.path("../");
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
    }
};



/**
 *위탁회사
 */
scwin.fn_getParTrstComInstCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_IsuItem.getCellData(1, "TRST_COM_ISUR_CD"); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_TRST_COM_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ISUR_ALL";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *위탁회사
 */
scwin.fn_SetParTrstComInstCd = function(arrPar) {
    dts_IsuItem.setCellData(1, "TRST_COM_ISUR_CD", arrPar[0]);
    txb_TRST_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


/**
 *사무관리
 */
scwin.fn_getParBzAdmComNm = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_IsuItem.getCellData(1, "BZ_ADM_COM_ISUR_CD"); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_BZ_ADM_COM_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ISUR_ALL";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *사무관리
 */
scwin.fn_SetParBzAdmComNm = function(arrPar) {
    dts_IsuItem.setCellData(1, "BZ_ADM_COM_ISUR_CD", arrPar[0]);
    txb_BZ_ADM_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};



/**
 *수탁회사
 */
scwin.fn_SetParTrstnIstCd = function(arrPar) {
    dts_IsuItem.setCellData(1, "TRST_INST_CD", arrPar[0]);
    txb_TRST_INST_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


/**
 * PF 종목정보 가져오는데 사용
 */
scwin.fn_getPfIsu_read_sync = function(exemBzProcsNo) {
    var url = "/pf/PfLstinvstg.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_EXEM_PF;
    url += "&BZ_PROCS_NO=" + exemBzProcsNo;
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
};
scwin.fn_read_sync = function() {
    var url = "/pf/PfLstinvstg.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_PF_ISU;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_LP_MBR_NO;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_LP.DataID = encodeURI(url);
    dts_LP.Reset();
    scwin.fn_initLpAndDistrPayGridData("N");
};

/**
 *	한글포함된 문자열 널값 및 최대길이 확인	*/
scwin.fn_checkValueNullMaxlength = function(vObj, vTitle) {
    var vMaxLength = vObj.maxLength;
    if ($c.stf.getObjectValue(vObj) == "") {
        $c.win.alert(vTitle + "을 입력하세요.");
        vObj.focus();
        return false;
    }
    if (fn_GetByte(vObj) > vMaxLength) {
        $c.win.alert("[" + vTitle + "] 입력길이가 " + vMaxLength + "자리를 초과할 수 없습니다.");
        vObj.focus();
        return false;
    }
    return true;
};



/*2010.07.30(2602) : 과세유형 추가*/
/**
 *	한글법인명 길이 확인
 */
scwin.fn_CheckForm = function() {
    fn_GetByte(txb_COM_NM.getValue());
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_SearchIsu.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다.");
        txb_ISU_SRT_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, $c.stf.getObjectValue(txb_ISU_CD))) return false;
    }
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_NM, "한글법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ABBRV, "한글법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_NM, "영문법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_ABBRV, "영문법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_NM, "한글종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_ABBRV, "한글종목약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_NM, "영문종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_ABBRV, "영문종목약명")) return false;
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_SYMBL) == "") {
            $c.win.alert("[영문법인심볼]을 입력하세요.");
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISUR_SYMBL))) {
            if (!$c.lc.fn_chkEtfCorpSymblDoubleInput($c.stf.getObjectValue(txb_ISUR_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_ENG_SYMBL) == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISU_ENG_SYMBL))) {
            if (!$c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(txb_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_ZIPCD) == "") {
        $c.win.alert("[우편번호]를 선택하세요.");
        img_ZIPCD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) == "") {
        $c.win.alert("[상장번호]를 선택하세요.");
        txb_LIST_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CORP_TEL_NO) == "") {
        $c.win.alert("[법인전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일(설정일)]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_COM_NM) == "") {
        $c.win.alert("[집합투자업자]을 선택하세요.");
        txb_TRST_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_BZ_ADM_COM_NM) == "") {
        $c.win.alert("[일반사무관리회사]을 입력하세요.");
        txb_BZ_ADM_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_INST_NM) == "") {
        $c.win.alert("[신탁업자(신탁회사)]을 입력하세요.");
        txb_TRST_INST_NM.focus();
        return false;
    }
    if ($c.pre_newlisting.fn_CheckGridDataset(dts_LP, "LP_MBR_NO")) {
        $c.win.alert("[LP회원명을]을 선택하세요.");
        return false;
    }


    //PF종목에는 해당되지않는항목
    dts_IsuItem.setCellData(1, "CEO_NM", '-');
    dts_IsuItem.setCellData(1, "STD_IND_CD", '-');
    dts_IsuItem.setCellData(1, "LIST_METHD_TP_CD", LIST_METHD_TP_CD_4);
    dts_IsuItem.setCellData(1, "ISU_RSN_CONTN", "신규상장");
    dts_IsuItem.setCellData(1, "REMK", "");
    return true;
};
